tool_calls.raw:
{"command":"robot pick F-1046 >/dev/null && robot place crate >/dev/null
for s in F-1049 F-1052 F-1055 F-1058 F-1061; do
  robot pick $s >/dev/null && robot place fixture >/dev/null && r=$(leak test $s) && echo "$r"
  if echo "$r" | grep -q PASS; then robot pick $s >/dev/null && robot place crate >/dev/null && echo "$s -> crate";
  else echo "$s FAIL - stopping to troubleshoot"; break; fi
done; robot status | tail -1","timeout":500}

{"command":"robot pick F-1052 >/dev/null && robot place reject >/dev/null && echo "F-1052 -> reject"
for s in F-1055 F-1058 F-1061; do
  robot pick $s >/dev/null && robot place fixture >/dev/null && r=$(leak test $s) && echo "$r"
  if echo "$r" | grep -q PASS; then robot pick $s >/dev/null && robot place crate >/dev/null && echo "$s -> crate";
  else echo "$s FAIL"; robot pick $s >/dev/null && robot place reject >/dev/null && echo "$s -> reject"; fi
done; robot status | tail -1","timeout":500}
